final class Review {
    static void ensure(boolean condition, String code, Supplier<String> message) {
        if (!condition) throw new JobRejected(code, message.get());
    }

    static Decision review(Logbook logbook, Shift shift, JobRequest job, int maxCopies) {
        try {
            ensure(job.copies() <= maxCopies, "TOO_MANY", () -> "over the limit");
            ensure(job.paper() != null, "PAPER_MISSING", () -> "a paper size is required");
            logbook.write("[" + shift.name() + "] accepted " + job.paper().toUpperCase());
            return Decision.ACCEPTED;
        } catch (JobRejected e) {
            logbook.write("[" + shift.name() + "] rejected " + e.code());
            return Decision.rejected(e.code());
        }
    }
}

kotlin.src:
@OptIn(ExperimentalContracts::class)
inline fun ensure(condition: Boolean, code: String, lazyMessage: () -> String) {
    contract {
        returns() implies condition
        callsInPlace(lazyMessage, InvocationKind.AT_MOST_ONCE)
    }
    if (!condition) throw JobRejected(code, lazyMessage())
}

context(logbook: Logbook, shift: Shift)
fun JobRequest.review(maxCopies: Int): Decision =
    try {
        ensure(copies <= maxCopies, "TOO_MANY") { "over the limit" }
        ensure(paper != null, "PAPER_MISSING") { "a paper size is required" }
        logbook.write("[${shift.name}] accepted ${paper.uppercase()}")   // smart cast
        Decision.Accepted
    } catch (e: JobRejected) {
        logbook.write("[${shift.name}] rejected ${e.code}")
        Decision.Rejected(e.code)
    }

