@OptIn(ExperimentalContracts::class)
inline fun <T : Any> ensureNotNull(value: T?, code: String, lazyMessage: () -> String): T {
    contract {
        returns() implies (value != null)                       // callers get a smart cast
        callsInPlace(lazyMessage, InvocationKind.AT_MOST_ONCE)
    }
    if (value == null) throw JobRejected(code, lazyMessage())
    return value
}

// it checks that contract { } comes first and warns on some callsInPlace mistakes;
// it never checks that the body keeps the returns-implies promise

